inline TVector<T> TQuat<T>::UnrotateVector(TVector<T> V) const
{	
	const TVector<T> Q(-X, -Y, -Z); // Inverse
	const TVector<T> TT = 2.f * TVector<T>::CrossProduct(Q, V);
	const TVector<T> Result = V + (W * TT) + TVector<T>::CrossProduct(Q, TT);
	return Result;

pub fn acceleration_amount(
    acceleration: Vec3,
    velocity: Vec3,
    rotation: Quat,
    maximum_acceleration: f32,
    maximum_braking_deceleration: f32,
) -> Vec2 {
    let maximum = if acceleration.dot(velocity) >= 0.0 {
        maximum_acceleration
    } else {
        maximum_braking_deceleration
    };
    if maximum <= 1e-6 {
        return Vec2::ZERO;
    }
    let amount = (acceleration / maximum).clamp_length_max(1.0);
    Vec2::new(
        amount.dot(rotation * Vec3::NEG_Z),
        amount.dot(rotation * Vec3::X),
    )
}

